using System.Collections.Generic;
using System.Web.Mvc;
using MundiAPI.PCL;
using MundiAPI.PCL.Models;

namespace MundipaggTest.Controllers {

    public class HomeController : Controller {

        public ActionResult Index () {

            // Secret key fornecida pela Mundipagg
            string basicAuthUserName = "SUA_CHAVE_SECRETA";
            // Senha em branco. Passando apenas a secret key
            string basicAuthPassword = "";

            var client = new MundiAPIClient (basicAuthUserName, basicAuthPassword);

            string planId = "plan_21r4CTG0ux77Qv13";

            var billinAddress = new CreateAddressRequest {
                Line1 = "375, Av. General Justo, Centro",
                Line2 = "8º andar",
                ZipCode = "20021130",
                City = "Rio de Janeiro",
                State = "RJ",
                Country = "BR"
            };

            var card = new CreateCardRequest {
                HolderName = "Tony Stark",
                Number = "4532464862385322",
                ExpMonth = 1,
                ExpYear = 30,
                Cvv = "903",
                BillingAddress = billinAddress
            };

            var discounts = new List<CreateDiscountRequest> {
                new CreateDiscountRequest {
                Cycles = 3,
                Value = 10,
                DiscountType = "percentage"
                }
            };

            var metadata = new Dictionary<string, string> ();
            metadata.Add ("id", "my_subscription_id");

            var request = new CreateSubscriptionRequest {
                PlanId = planId,
                PaymentMethod = "credit_card",
                Currency = "BRL",
                Interval = "month",
                IntervalCount = 3,
                BillingType = "prepaid",
                Installments = 3,
                Customer = new CreateCustomerRequest {
                Name = "Tony Stark",
                Email = "tonystark@avengers.com"
                },
                Card = card,
                Discounts = discounts,
                Metadata = metadata
            };

            var response = client.Subscriptions.CreateSubscription (request);

            return View ();
        }
    }
}

